  runtime.FRAG = ["#version 300 es", "precision highp float;", "uniform vec2 iResolution;uniform float iTime;uniform float uSpeed;uniform float uWaveDepth;", "uniform float uZoom;uniform float uDensity;uniform float uSpread;uniform float uStepSize;", "uniform float uGlow;uniform float uExposure;uniform float uColorShift;uniform float uContrast;", "uniform float uBrightness;uniform float uOpacity;uniform float uSteps;", "uniform vec3 uColor1;uniform vec3 uColor2;uniform vec3 uColor3;", "uniform vec2 uMouse;uniform float uMouseStrength;uniform float uMouseRadius;", "uniform float uEnableMouse;uniform float uMouseActive;uniform float uGrain;", "uniform float uGrainIntensity;uniform float uLightMode;", "out vec4 fragColor;", "void main(){", "vec2 frag=gl_FragCoord.xy;float zoom=max(uZoom,0.05);float aspect=iResolution.x/iResolution.y;", "vec2 ndc=(2.0*frag-iResolution.xy)/iResolution.y;vec2 dir=ndc*(0.5/zoom);", "vec2 mouseNdc=vec2(uMouse.x*aspect,uMouse.y);float mr=max(uMouseRadius,0.01);", "vec2 md=ndc-mouseNdc;float dent=exp(-dot(md,md)/(mr*mr))*(3.0*uMouseStrength*uEnableMouse*uMouseActive);", "float travel=sin(iTime*uSpeed)*uWaveDepth;float density=max(uDensity,1.0);", "float spread=clamp(uSpread,0.05,0.6);float stepSize=max(uStepSize,0.0005);", "float glowGain=max(uGlow,0.0);", "vec3 tOffset=vec3(0.0,dent,travel);vec3 p=vec3(0.0);float s=0.0;float glow=0.0;", "for(int i=0;i<64;i++){if(float(i)>=uSteps)break;p+=vec3(dir*s,s);vec3 q=p+tOffset;", "s+=density-length(q.xz)+length(ceil(q).xy);s=stepSize+abs(s)*spread;glow+=glowGain/s;}", "float e=glow/max(uExposure,1.0);", "float shimmer=0.5+0.5*dot(cos(iTime*uColorShift+p),vec3(0.3333));", "float v=tanh(e*uBrightness*mix(0.7,1.05,shimmer));", "v=clamp((v-0.5)*uContrast+0.5,0.0,1.0);", "vec3 col=mix(uColor1,uColor2,smoothstep(0.0,0.55,v));", "col=mix(col,uColor3,smoothstep(0.55,1.0,v));col*=v;", "float a=clamp(v,0.0,1.0)*uOpacity;vec3 outRgb=col*a;", "if(uGrain>0.5){float gv=(fract(sin(dot(gl_FragCoord.xy,vec2(12.9898,78.233))+iTime)*43758.5453)-0.5)*uGrainIntensity;", "outRgb=clamp(outRgb+gv,0.0,1.0);a=clamp(a+gv,0.0,1.0);}", "if(uLightMode>0.5){float peak=max(col.r,max(col.g,col.b));", "vec3 chroma=pow(clamp(col/max(peak,0.0001),0.0,1.0),vec3(1.16));", "fragColor=vec4(mix(vec3(1.0),chroma,a*0.94),1.0);}else{fragColor=vec4(outRgb,a);}}"].join("\n");

